def find_product(nums):
    """
    This function finds the product of non-repeated elements in a given list of integers.

    Args:
        nums (list): A list of integers.

    Returns:
        int: The product of non-repeated elements in the list.

    Raises:
        TypeError: If the input is not a list of integers.
    """
    # Check if the input is a list
    if not isinstance(nums, list):
        raise TypeError("Input must be a list.")

    # Check if all elements in the list are integers
    if not all(isinstance(num, int) for num in nums):
        raise TypeError("All elements in the list must be integers.")

    # Create a dictionary to store the frequency of each element
    freq_dict = {}
    for num in nums:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Initialize the product variable
    product = 1

    # Iterate over the dictionary to find non-repeated elements
    for num, freq in freq_dict.items():
        if freq == 1:
            product *= num

    return product

