import struct

def pack(format_string: str, *args: tuple) -> bytes:
    """
    Packs the input arguments into a binary string according to the given format.

    Args:
        format_string (str): The format string that specifies the format of the returned string.
        *args: The input arguments to be packed.

    Returns:
        bytes: The packed binary string.

    Raises:
        ValueError: If the format string is invalid or the number of arguments does not match the format string.
    """
